# Aktifkan stub_status (hanya dari localhost)
server {
    listen 127.0.0.1:80;
    server_name localhost;

    location /nginx_status {
        stub_status;
        allow 127.0.0.1;
        deny all;
    }
}

# Sesuaikan dengan jumlah core CPU (cek dengan: nproc)
worker_processes auto;
worker_rlimit_nofile 65535;

events {
    worker_connections 4096;
    use epoll;
    multi_accept on;
}

http {
    # Pakai ulang koneksi ke upstream, jangan buka-tutup tiap request
    upstream backend {
        server 127.0.0.1:8080;
        keepalive 32;
    }
}

# Starter pack: cache + kompresi dalam satu location
location / {
    proxy_cache app_cache;
    proxy_cache_valid 200 10m;
    proxy_pass http://backend;
}

# Kompresi untuk semua respons teks
gzip on;
gzip_comp_level 6;
gzip_types text/plain text/css application/javascript application/json;
